# encoding: utf-8
# Writes plugins/Prismfall Field Effects/011_FieldEffects_MapDefaults.rb from
# design/FIELD_DEFAULTS.yaml: the interim per-map default fields
# (FieldEffects::MAP_DEFAULT_FIELDS / MAP_DEFAULT_WILD_FIELDS), the per-map
# pools of open borrowing fields such as the Bleed (MAP_BORROW_POOLS, from a
# map's `borrow:` list) and the trainer exceptions (TRAINER_FIELDS). mapgen's
# MAP_FIELDS still win where present.
#
#   ruby tools/field_defaults_to_rb.rb [--check]
#
# --check: exit 1 if the generated file is out of date (no write).
require "yaml"

ROOT = File.expand_path("..", __dir__)
SRC  = File.join(ROOT, "design", "FIELD_DEFAULTS.yaml")
DEST = File.join(ROOT, "plugins", "Prismfall Field Effects", "011_FieldEffects_MapDefaults.rb")

data = YAML.safe_load(File.read(SRC, encoding: "UTF-8"))
known = Dir[File.join(ROOT, "plugins", "Prismfall Field Effects", "1*_Field_*.rb")].flat_map { |f|
  File.read(f, encoding: "UTF-8").scan(/FieldEffects\.register\(:([A-Z_]+)/).flatten
}
errors = []

def entry(field, stage)
  return ":NONE" if field.to_s.upcase == "NONE"
  return (stage && stage.to_i > 1) ? "[:#{field}, #{stage.to_i}]" : ":#{field}"
end

check = lambda do |field, where|
  f = field.to_s.upcase
  errors << "#{where}: unknown field #{field.inspect}" if f != "NONE" && !known.include?(f)
end

out = []
out << "# GENERATED by tools/field_defaults_to_rb.rb from design/FIELD_DEFAULTS.yaml - do not edit."
out << "# Interim map defaults: used only where mapgen's MAP_FIELDS / MAP_WILD_FIELDS have no entry."
out << "module FieldEffects"
out << "  MAP_DEFAULT_FIELDS.merge!({"
wild = []
pools = []
data["maps"].sort_by { |k, _| k.to_i }.each do |id, m|
  check.call(m["field"], "map #{id}")
  out << format("    %d => %s,   # %s", id.to_i, entry(m["field"], m["stage"]), m["name"].to_s.gsub(/[^\x20-\x7E]/, "?"))
  if m["wild"]
    check.call(m["wild"], "map #{id} wild")
    wild << format("    %d => %s,   # %s", id.to_i, entry(m["wild"], m["wild_stage"]), m["name"].to_s.gsub(/[^\x20-\x7E]/, "?"))
  end
  if m["borrow"]
    list = Array(m["borrow"])
    list.each { |f| check.call(f, "map #{id} borrow") }
    errors << "map #{id} borrow: NONE is not a field" if list.any? { |f| f.to_s.upcase == "NONE" }
    pools << format("    %d => [%s],   # %s", id.to_i, list.map { |f| ":#{f.to_s.upcase}" }.join(", "),
                    m["name"].to_s.gsub(/[^\x20-\x7E]/, "?"))
  end
end
out << "  })"
out << "  MAP_DEFAULT_WILD_FIELDS.merge!({"
out.concat(wild)
out << "  })"
out << "  MAP_BORROW_POOLS.merge!({"
out.concat(pools)
out << "  })"
out << "  TRAINER_FIELDS.merge!({"
Array(data.dig("exceptions", "trainers")).each do |t|
  check.call(t["field"], "trainer #{t["trainer"]}")
  val = entry(t["field"], t["stage"])
  if t["versions"]
    Array(t["versions"]).each { |v| out << format("    [:%s, %d] => %s,   # %s", t["trainer"], v.to_i, val, t["why"].to_s[0, 60]) }
  else
    out << format("    :%s => %s,   # %s", t["trainer"], val, t["why"].to_s[0, 60])
  end
end
out << "  })"
out << "end"
text = out.join("\n") + "\n"

if !errors.empty?
  warn errors.join("\n")
  exit 1
end
if ARGV.include?("--check")
  same = File.exist?(DEST) && File.read(DEST) == text
  puts(same ? "011_FieldEffects_MapDefaults.rb is up to date" : "011_FieldEffects_MapDefaults.rb is OUT OF DATE")
  exit(same ? 0 : 1)
end
File.write(DEST, text, encoding: "UTF-8")
puts "wrote #{DEST} (#{data["maps"].size} maps, #{wild.size} wild overrides, #{pools.size} borrow pools)"
